{
  "case_id": "CASE_0290",
  "bail_granted": true,
  "reasoning": "The offence is of modest gravity and evidence is partly recovered. The accused, a female, has spent 9 months in custody without trial. Flight risk and tampering are mitigated by her eventual arrest and recovery. Regular bail is warranted under Article 21 and legal principles of bail.",
  "relevant_acts": [
    "CrPC s.439",
    "IPC s.392",
    "BNSS s.480"
  ]
}

{
  "case_id": "CASE_1118",
  "bail_granted": false,
  "reasoning": "Gravity is high as it involves fraud, conspiracy, and proceeds of crime exceeding ₹50 crores under PMLA and IPC s.420. Document seizure supports prosecution case. Though she joined investigations, the restrictive bar under PMLA s.45 and risk of tampering warrants custody. Time already spent is insufficient to offset gravity.",
  "relevant_acts": [
    "IPC s.420",
    "PMLA s.45",
    "BNSS s.480"
  ]
}

{
  "case_id": "CASE_0834",
  "bail_granted": true,
  "reasoning": "Bail is granted. The offence, though 498A, is counter-litigation/retaliatory. The applicant is a woman unlikely to abscond. She has cooperated with the investigation. No period of custody is mentioned to weigh against relief. The alleged misappropriation from a joint locker lacks the seriousness to warrant detention.",
  "relevant_acts": [
    "IPC s.498A",
    "CrPC s.438"
  ]
}

{
  "case_id": "CASE_0699",
  "bail_granted": true,
  "reasoning": "Cyber fraud under IPC s.420 is bailable; the accused is entitled to bail as a matter of right. Recovery of phones is probative but does not negate the right. Tampering concerns may be addressed through conditions such as device surrender. Period in custody is not a bar to grant. Parity with co-accused is immaterial given the bailable nature.",
  "relevant_acts": ["IPC s.420", "CrPC s.439"]
}

{
  "case_id": "CASE_0655",
  "bail_granted": true,
  "reasoning": "The petitioner is already on bail for the same alleged act; no fresh evidence or exceptional gravity is shown. The second FIR appears retaliatory, and there is no indication of absconding or evidence tampering. Anticipatory bail is warranted to prevent harassment.",
  "relevant_acts": [
    "BNSS s.482",
    "CrPC s.438"
  ]
}

{
  "case_id": "CASE_0260",
  "bail_granted": true,
  "reasoning": "The offence is attempted robbery under IPC s.395 punishable up to seven years. The charge-sheet is filed but the offence is not of extreme gravity, and the accused was apprehended at the scene. There is no serious flight risk, and conditions can mitigate tampering. Hence bail is granted with surety.",
  "relevant_acts": [
    "IPC s.395",
    "CrPC s.439",
    "BNSS s.480"
  ]
}
